import React from 'react';
import {cva} from 'class-variance-authority';
const classes = cva("inline-flex items-center justify-center rounded font-medium disabled:opacity-50", {
  variants: {
    tone: {primary: "bg-action text-on-action", secondary: "bg-slate-100 text-slate-900", danger: "bg-red-100 text-red-900"},
    size: {sm: "px-3 py-1 text-sm", lg: "px-4 py-2 text-base"}
  },
  defaultVariants: {tone: "primary", size: "sm"}
});
export default function ActionButton({tone,size,className,...props}) {
  return <button {...props} className={classes({tone: tone === undefined ? undefined : tone === "primary" || tone === "danger" ? tone : "secondary", size: size === undefined ? undefined : size === "sm" ? "sm" : "lg", className})}/>;
}

import React from 'react';
import {cva} from 'class-variance-authority';
const classes = cva("inline-flex rounded font-medium", {
  variants: {
    status: {idle: "bg-slate-100 text-slate-900", loading: "bg-amber-100 text-amber-900", success: "bg-green-100 text-green-900", error: "bg-red-100 text-red-900", queued: "bg-amber-100 text-amber-900"},
    density: {compact: "px-1 py-0.5 text-xs", comfortable: "px-2 py-1 text-sm"}
  },
  defaultVariants: {status: "idle", density: "compact"}
});
export default function StatusBadge({status,density,className,...props}) {
  return <span {...props} className={classes({status: status === undefined ? undefined : ["idle","loading","success","queued"].includes(status) ? status : "error", density: density === undefined ? undefined : density === "compact" ? "compact" : "comfortable", className})}/>;
}

import React from 'react';
import {cva} from 'class-variance-authority';
const classes = cva("rounded border", {
  variants: {
    tone: {neutral: "border-slate-200 bg-white", accent: "border-action bg-white"},
    density: {compact: "p-2", comfortable: "p-4", spacious: "p-6"}
  },
  defaultVariants: {tone: "neutral", density: "comfortable"}
});
export default function PanelCard({tone,density,className,...props}) {
  return <section {...props} className={classes({tone: tone === undefined ? undefined : tone === "neutral" ? "neutral" : "accent", density: density === undefined ? undefined : density === "compact" || density === "spacious" ? density : "comfortable", className})}/>;
}

import assert from 'node:assert/strict';
import {test} from 'node:test';
import {build} from '../runtime/node_modules/esbuild/lib/main.js';
import {mkdtemp, writeFile, rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createRequire} from 'node:module';

const bundle = await build({
  stdin: {
    contents: `
      import React from 'react';
      import {renderToStaticMarkup} from 'react-dom/server';
      import ActionButton from './ui/ActionButton.jsx';
      import StatusBadge from './ui/StatusBadge.jsx';
      import PanelCard from './ui/PanelCard.jsx';
      export {React, renderToStaticMarkup, ActionButton, StatusBadge, PanelCard};
    `,
    resolveDir: process.cwd(),
    sourcefile: 'variant-expansion-ssr.jsx',
    loader: 'jsx'
  },
  bundle: true,
  platform: 'node',
  format: 'cjs',
  write: false
});
const testDir = await mkdtemp(join(tmpdir(), 'variant-expansion-'));
const bundlePath = join(testDir, 'bundle.cjs');
await writeFile(bundlePath, bundle.outputFiles[0].text);
const {React, renderToStaticMarkup, ActionButton, StatusBadge, PanelCard} =
  createRequire(import.meta.url)(bundlePath);
await rm(testDir, {recursive: true, force: true});

const render = (Component, props) =>
  renderToStaticMarkup(React.createElement(Component, props, '내용'));

test('new CVA variants render through their public props and retain native attributes', () => {
  const button = render(ActionButton, {tone: 'danger', size: 'lg', disabled: true, className: 'caller'});
  assert.match(button, /^<button /);
  assert.match(button, /disabled=""/);
  assert.match(button, /bg-red-100 text-red-900/);
  assert.match(button, /px-4 py-2 text-base/);
  assert.match(button, /caller/);
  assert.match(button, />내용<\/button>$/);

  const badge = render(StatusBadge, {status: 'queued', density: 'comfortable', title: '대기', className: 'caller'});
  assert.match(badge, /^<span /);
  assert.match(badge, /title="대기"/);
  assert.match(badge, /bg-amber-100 text-amber-900/);
  assert.match(badge, /px-2 py-1 text-sm/);
  assert.match(badge, /caller/);
  assert.match(badge, />내용<\/span>$/);

  const panel = render(PanelCard, {tone: 'accent', density: 'spacious', 'aria-label': '넓은 패널', className: 'caller'});
  assert.match(panel, /^<section /);
  assert.match(panel, /aria-label="넓은 패널"/);
  assert.match(panel, /border-action bg-white/);
  assert.match(panel, /p-6/);
  assert.match(panel, /caller/);
  assert.match(panel, />내용<\/section>$/);
});

import assert from 'node:assert/strict';
import {test} from 'node:test';
import {build} from '../runtime/node_modules/esbuild/lib/main.js';
import {mkdtemp,writeFile,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createRequire} from 'node:module';

const source = `
  import React from 'react';
  import {renderToStaticMarkup} from 'react-dom/server';
  import App from './App.jsx';
  import ActionButton from './ui/ActionButton.jsx';
  import PanelCard from './ui/PanelCard.jsx';
  import StatusBadge from './ui/StatusBadge.jsx';
  export {React,renderToStaticMarkup,App,ActionButton,PanelCard,StatusBadge};
`;
const bundle = await build({
  stdin: {contents: source, resolveDir: process.cwd(), sourcefile: 'ui-style-ssr.jsx', loader: 'jsx'},
  bundle: true,
  platform: 'node',
  format: 'cjs',
  write: false
});
const testDir = await mkdtemp(join(tmpdir(), 'ui-style-'));
const bundlePath = join(testDir, 'bundle.cjs');
await writeFile(bundlePath, bundle.outputFiles[0].text);
const {React,renderToStaticMarkup,App,ActionButton,PanelCard,StatusBadge} = createRequire(import.meta.url)(bundlePath);
await rm(testDir, {recursive: true, force: true});
const render = (Component, props, children = '내용') =>
  renderToStaticMarkup(React.createElement(Component, props, children));

test('variant components preserve defaults, alternates and native props', () => {
  const button = render(ActionButton, {id: 'pay', disabled: true, className: 'caller'});
  assert.match(button, /id="pay"/);
  assert.match(button, /disabled=""/);
  assert.match(button, /bg-action text-on-action/);
  assert.match(button, /px-3 py-1 text-sm/);
  assert.match(button, /caller/);
  assert.match(button, />내용<\/button>/);
  assert.match(render(ActionButton, {tone: 'secondary', size: 'lg'}), /bg-slate-100 text-slate-900/);
  assert.match(render(ActionButton, {tone: 'secondary', size: 'lg'}), /px-4 py-2 text-base/);
  assert.match(render(ActionButton, {tone: 'unknown', size: 'unknown'}), /bg-slate-100 text-slate-900.*px-4 py-2 text-base/);

  const panel = render(PanelCard, {'aria-label': '주문', className: 'caller'});
  assert.match(panel, /aria-label="주문"/);
  assert.match(panel, /border-slate-200 bg-white/);
  assert.match(panel, /p-4/);
  assert.match(panel, /caller/);
  assert.match(panel, />내용<\/section>/);
  assert.match(render(PanelCard, {tone: 'accent', density: 'compact'}), /border-action bg-white/);
  assert.match(render(PanelCard, {tone: 'accent', density: 'compact'}), /p-2/);
  assert.match(render(PanelCard, {tone: 'unknown', density: 'unknown'}), /border-action bg-white.*p-4/);

  const badge = render(StatusBadge, {title: '상태', className: 'caller'});
  assert.match(badge, /title="상태"/);
  assert.match(badge, /bg-slate-100 text-slate-900/);
  assert.match(badge, /px-1 py-0.5 text-xs/);
  assert.match(badge, /caller/);
  assert.match(badge, />내용<\/span>/);
  for (const [status, className] of [
    ['loading', 'bg-amber-100 text-amber-900'],
    ['success', 'bg-green-100 text-green-900'],
    ['error', 'bg-red-100 text-red-900']
  ]) assert.match(render(StatusBadge, {status, density: 'comfortable'}), new RegExp(`${className}.*px-2 py-1 text-sm`));
  assert.match(render(StatusBadge, {status: 'unknown', density: 'unknown'}), /bg-red-100 text-red-900.*px-2 py-1 text-sm/);
});

test('console initial markup keeps its labels, status regions and amount output', () => {
  const resource = {getState: () => ({items: [], status: 'idle', error: null})};
  const system = {
    orders: resource, inventory: resource, returns: resource, wallet: resource,
    checkout: {submit() {}}, refund: {submit() {}}, login() {}, logout() {}
  };
  const html = renderToStaticMarkup(React.createElement(App, {system, checkoutInput: {}, refundInput: {}}));
  for (const label of ['운영 콘솔', '주문 조회', '재고 조회', '반품 조회', '지갑 조회', '결제', '환불', '로그인', '로그아웃'])
    assert.ok(html.includes(label), label);
  assert.equal((html.match(/role="status"/g) ?? []).length, 4);
  assert.match(html, /aria-label="세션 토큰" type="password"/);
  assert.match(html, /class="mx-auto max-w-5xl space-y-4 p-6"/);
});

import React from 'react';
import OrderPanel from './ui/OrderPanel.jsx';
import InventoryPanel from './ui/InventoryPanel.jsx';
import ReturnsPanel from './ui/ReturnsPanel.jsx';
import WalletPanel from './ui/WalletPanel.jsx';
import CheckoutForm from './ui/CheckoutForm.jsx';
import ReturnForm from './ui/ReturnForm.jsx';
import SessionBar from './ui/SessionBar.jsx';
export default function App({system, checkoutInput, refundInput}) {
  return <main className="mx-auto max-w-5xl space-y-4 p-6"><h1>운영 콘솔</h1><SessionBar onLogin={system.login} onLogout={system.logout}/>
    <OrderPanel orders={system.orders}/><InventoryPanel inventory={system.inventory}/>
    <ReturnsPanel returns={system.returns}/><WalletPanel wallet={system.wallet}/>
    <CheckoutForm checkout={system.checkout} input={checkoutInput}/><ReturnForm refund={system.refund} input={refundInput}/></main>;
}

import ActionButton from './ActionButton.jsx';
import React from 'react';
import {useAction} from './useAction.mjs';
export default function CheckoutForm({checkout, input}) {
  const action = useAction(() => checkout.submit(input));
  return <section><ActionButton disabled={action.pending} onClick={action.run}>결제</ActionButton>
    {action.result && <output>{action.result.order.id}</output>}
    {action.error && <p role="alert">결제에 실패했습니다.</p>}</section>;
}

import ActionButton from './ActionButton.jsx';
import React from 'react';
import {useAction} from './useAction.mjs';
export default function ReturnForm({refund, input}) {
  const action = useAction(() => refund.submit(input));
  return <section><ActionButton disabled={action.pending} onClick={action.run}>환불</ActionButton>
    {action.result && <output>{action.result.record.id}{action.result.restockPending ? ' 재입고 대기' : ''}</output>}
    {action.error && <p role="alert">환불에 실패했습니다.</p>}</section>;
}

import StatusBadge from './StatusBadge.jsx';
import React from 'react';
export default function Status({state}) {
  return <div><p role="status"><StatusBadge status={state.status}>{state.status}</StatusBadge></p>{state.error && <p role="alert">요청을 처리하지 못했습니다.</p>}</div>;
}

import PanelCard from './PanelCard.jsx';
import ActionButton from './ActionButton.jsx';
import React from 'react';
import {useAction} from './useAction.mjs';
import Status from './Status.jsx';
export default function OrderPanel({orders}) {
  const action = useAction(async () => { await orders.load(); return orders.getState(); });
  const state = action.result ?? orders.getState();
  return <PanelCard aria-label="주문"><ActionButton disabled={action.pending} onClick={action.run}>주문 조회</ActionButton>
    <Status state={state}/><ul>{state.items.map(item => <li key={item.id}>{item.id}</li>)}</ul></PanelCard>;
}

